import type { AssetManifest, Overrides } from "./schema";

export async function loadJson<T>(url: string): Promise<T> {
  const res = await fetch(url, { cache: "no-store" });
  if (!res.ok) throw new Error(`Failed to load ${url}: ${res.status}`);
  return (await res.json()) as T;
}

export async function loadManifestAndOverrides() {
  const [manifest, overrides] = await Promise.all([
    loadJson<AssetManifest>("/assets/manifest.json"),
    loadJson<Overrides>("/configs/overrides.json")
  ]);
  return { manifest, overrides };
}

